('srd35_equipment_gear_sled','Sled','gear',NULL,NULL,NULL,NULL,NULL,NULL,300,20,'SRD 3.5 · gear','https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md','gear',NULL,NULL,20,'{"cost_text":"20 gp","weight_text":"300 lb.","section":"gear","source_url":"https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md","open_game_content":true}'::jsonb),
('srd35_equipment_gear_wagon','Wagon','gear',NULL,NULL,NULL,NULL,NULL,NULL,400,35,'SRD 3.5 · gear','https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md','gear',NULL,NULL,35,'{"cost_text":"35 gp","weight_text":"400 lb.","section":"gear","source_url":"https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md","open_game_content":true}'::jsonb),
('srd35_equipment_gear_warship','Warship','gear',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'SRD 3.5 · gear','https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md','gear',NULL,NULL,0,'{"cost_text":"25,000 gp","weight_text":"—","section":"gear","source_url":"https://github.com/olimot/srd-v3.5-md/blob/main/basic-rules-and-legal/equipment.md","open_game_content":true}'::jsonb)
on conflict(id) do update set nome=case when srd_equipment.srd_source_url is null then srd_equipment.nome else excluded.nome end,tipo=excluded.tipo,dano=excluded.dano,critico=excluded.critico,tipo_dano=excluded.tipo_dano,ca_bonus=excluded.ca_bonus,max_des=excluded.max_des,penalidade_armadura=excluded.penalidade_armadura,peso=excluded.peso,preco=excluded.preco,descricao=excluded.descricao,srd_source_url=excluded.srd_source_url,categoria=excluded.categoria,bonus_ca=excluded.bonus_ca,bonus_max_des=excluded.bonus_max_des,custo_po=excluded.custo_po,detalhes=excluded.detalhes;
